+                icicle: d => [(d.x0+d.x1)/2 - width/2, d.y0 - icicleHeight/2],
+                dendrogram: d => [d.y - (width-100)/2, d.x - (height-100)/2],
+                radial: polar, cluster: polar,
+                partition: d => arc.centroid(d),
+            }[currentLayout] || (d => [d.current_x, d.current_y]);
+            const noTransformPrev = previousLayout === 'partition' || previousLayout === 'icicle';
             root.descendants().forEach(d => {
                 d.source_x = d.current_x;
                 d.source_y = d.current_y;
-                const noTransformPrev = previousLayout === 'partition' || previousLayout === 'icicle';
-                const [source_transform_x, source_transform_y] = noTransformPrev ? [0, 0] : [d.source_x, d.source_y];
-
-                if (currentLayout === "pack") {
-                    d.target_x = d.x - width/2; d.target_y = d.y - height/2;
-                } else if (currentLayout === "treemap" || currentLayout === "icicle") {
-                    d.target_x = (d.x0 + d.x1)/2 - width/2;
-                    d.target_y = currentLayout === "icicle" ? d.y0 - icicleHeight/2 : (d.y0 + d.y1)/2 - height/2;
