-                    d.target_x = d.y - (width-100)/2; d.target_y = d.x - (height-100)/2;
-                } else if (currentLayout === "radial" || currentLayout === "cluster") {
-                    d.target_x = d.y * Math.cos(d.x - Math.PI/2); d.target_y = d.y * Math.sin(d.x - Math.PI/2);
-                } else if (currentLayout === "partition") {
-                    [d.target_x, d.target_y] = arc.centroid(d);
-                } else {
-                    d.target_x = d.current_x; d.target_y = d.current_y;
-                }
-
-                const [target_transform_x, target_transform_y] = currentLayout === 'partition' ? [0, 0]
+                const [sx, sy] = noTransformPrev ? [0, 0] : [d.source_x, d.source_y];
+                [d.target_x, d.target_y] = targetPos(d);
+                const [tx, ty] = currentLayout === 'partition' ? [0, 0]
                     : [d.target_x, currentLayout === 'icicle' ? (d.y0 + d.y1)/2 - icicleHeight/2 : d.target_y];
-                
                 const dataInterpolator = d3.interpolate({x: d.source_x, y: d.source_y}, {x: d.target_x, y: d.target_y});
-                const transformInterpolator = d3.interpolate({x: source_transform_x, y: source_transform_y}, {x: target_transform_x, y: target_transform_y});
+                const transformInterpolator = d3.interpolate({x: sx, y: sy}, {x: tx, y: ty});
                 nodeInterpolators.set(d.id, { data: dataInterpolator, transform: transformInterpolator });
             });
